/*! Bundled license information:

poker-extval/src/cards.js:
  (**
   * Card helpers: parsing, ranking, sorting and validation.
   *
   * Cards are two-character strings: a rank (A, K, Q, J, T, 9-2) followed by a suit (s, h, d, c),
   * e.g. 'As', 'Td'. Every helper here is pure; none of them reorders its input.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/flags.js:
  (**
   * The evaluation flags and the groups they belong to. Every list is defined once here.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/lazy.js:
  (**
   * Lazy properties: computed the first time they are read, then stored as plain values.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/analyze.js:
  (**
   * Analyses a single 5-card hand: made hands, position labels, draws and hole card categories,
   * plus the key cards and kicker cards behind every flag that is true.
   *
   * Everything here is a pure function of the five cards and a context describing the full hand
   * (see buildContext), so the same five cards always give the same result.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/score.js:
  (**
   * Fast hand scoring with plain numbers, using poker-bitvaljs's public fast evaluator (1.9.0+).
   *
   * A set of cards is four 13-bit "suit lanes" (one rank mask per suit, in poker-bitvaljs's order).
   * A score is an integer: higher beats lower, equal values tie, and `score >>> 20` is the made-hand
   * category. poker-bitvaljs documents this format as stable across versions.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/evaluate.js:
  (**
   * Evaluates a full hand of 5 or more cards: every 5-card combination, or in strict mode the
   * best one (found by scoring every five) with the draws of the whole hand.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/range.js:
  (**
   * Villain ranges: parsing (via poker-rangeman) and blocker classification.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/compare.js:
  (**
   * Hand comparison and equity, using poker-bitvaljs.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/analysis.js:
  (**
   * Hand analysis: graded outs, hand strength, and (against a villain range) equity, equity now,
   * draw equity, the next-card spread and runner-runner equity.
   *
   * Every runout is enumerated exactly; nothing is sampled. Hands are scored through src/score.js,
   * with card sets held as four 13-bit suit lanes.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/src/hand.js:
  (**
   * The chainable hand API: hand(cards, options) returns a HandView whose methods each work out only
   * what they return, the first time they are called, and remember it.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)

poker-extval/evaluator.js:
  (**
   * Poker Hand Evaluator
   *
   * Evaluates poker hands from 5 or more cards and identifies all possible made hands and draws.
   * For inputs with more than 5 cards, generates all possible 5-card combinations and evaluates each one.
   *
   * @license MIT
   * @copyright Copyright (c) 2025 Darragh Geoghegan
   *)
*/
